-- The CHATTER-FREE code key (Code keys -> Milling -> CHATTER-FREE), from the ISCAR
-- e-catalog's CHATTER-FREE families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.chatterfree', $ck${"title": "CHATTER-FREE code key – solid carbide endmills with variable pitch", "subtitle": "Solid carbide endmills with different helix and variable pitch for chatter damping, for steel, stainless steel, hard materials and aluminum", "example": "EC-H4M 06-12C06CFR0.2-57", "decoder": "chatter-free", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "EC", "rows": [{"code": "EC", "meaning": "Endmill"}, {"code": "ECA", "meaning": "Endmill for machining aluminum"}, {"code": "ECAP", "meaning": "Aluminum endmill with chip splitters and coolant holes"}, {"code": "ECP", "meaning": "Endmill with chip splitting cutting edges"}, {"code": "ECY", "meaning": "Endmill for austenitic, duplex, cast and precipitation hardening stainless steels"}, {"code": "EB", "meaning": "Ball nose endmill"}, {"code": "KIT", "meaning": "Kit of endmills"}]}, {"key": "t-helix", "title": "Helix", "rows": [{"code": "E", "meaning": "38° helix"}, {"code": "H", "meaning": "Different helix and variable pitch (CHATTER-FREE)"}, {"code": "S", "meaning": "Geometry S (see the catalog)"}]}, {"key": "t-flutes", "title": "Number of flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-length", "title": "Length", "rows": [{"code": "L", "meaning": "Long, with a 3xD relieved neck"}, {"code": "M", "meaning": "Medium length"}, {"code": "S", "meaning": "Short"}, {"code": "XL", "meaning": "Extra long"}]}, {"key": "t-dims", "title": "Geometry / dimension code", "rows": [{"code": "…", "meaning": "Further code (see the catalog)"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-apmx", "title": "Cutting length", "rows": [{"code": "##", "meaning": "Cutting length in mm"}]}, {"key": "t-neck", "title": "Neck (reach) length", "rows": [{"code": "/##", "meaning": "Length to the neck end in mm"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}, {"code": "SL", "meaning": "Safe-Lock shank (by Haimer), helical grooves that prevent pull-out"}, {"code": "W", "meaning": "Weldon shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-cf", "title": "CHATTER-FREE", "rows": [{"code": "CF", "meaning": "CHATTER-FREE: different helix and variable pitch for chatter damping"}]}, {"key": "t-corner", "title": "Corner", "rows": [{"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (R02 = 0.2 mm)"}, {"code": "RP#.#", "meaning": "Programmed radius (Rg) for CAM"}]}, {"key": "t-line", "title": "Line (before the overall length)", "rows": [{"code": "E", "meaning": "Economical line (TEC)"}, {"code": "H", "meaning": "For hard materials (see the catalog)"}, {"code": "M", "meaning": "Line M (see the catalog)"}, {"code": "S", "meaning": "Line S (chip splitting) (see the catalog)"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "C", "meaning": "With coolant holes / channels"}, {"code": "D", "meaning": "Version D (see the catalog)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
